//! Computed frames and their derived indexes for one lineage. Geometry edits
//! invalidate this cache in reference order; history is materialized only when
//! an edit needs it. Copying the cache resets its borrowed query shortcuts.

use crate::grid::{FlatIntMap, IntMap};
use crate::frame_states::FrameStates;
use crate::history::CollisionHistory;
use crate::kernel::{
    init_state, step_state, CollisionTrace, LineCellCache, State,
};
use crate::line::{push_line, remove_line, LineRef};
use crate::{
    BUTT, LFOOT, LHAND, NENT, NOSE, PEG, RFOOT, RHAND, RIDER_MOUNTED, SHOULDER, SLED_INTACT,
    STRING, TAIL,
};
use std::cell::OnceCell;

// parts.BODY in lr-core order — the entities getRider averages (sum in this order
// then /6, matching Rider.getBody's averageVectors so the result is bit-identical).
const BODY: [usize; 6] = [BUTT, SHOULDER, RHAND, LHAND, LFOOT, RFOOT];
const SLED_POINT_MASK: u32 = (1u32 << PEG) | (1u32 << TAIL) | (1u32 << NOSE) | (1u32 << STRING);
type Event = crate::kernel::Collision;

#[derive(Clone)]
pub(crate) struct FrameSummary {
    pub(crate) body_px: f64,
    pub(crate) body_py: f64,
    pub(crate) body_vx: f64,
    pub(crate) body_vy: f64,
    pub(crate) rider_fsu: i32,
    pub(crate) sled_fsu: i32,
    pub(crate) sled_points: [u8; 4], // first-contact order
    pub(crate) sled_count: u8,
    motion: OnceCell<[f64; 4]>, // pure observation; shared snapshots may fill it without copying
    pub(crate) contact_offset: usize,
    pub(crate) contact_count: usize,
}

// ── the single shared cache per lineage (LineEngine.__computed__ + Frame.grid/collisions) ──
#[derive(Clone)]
pub(crate) struct FrameCache {
    cell_lines: FlatIntMap<Vec<LineRef>>, // ClassicGrid cellLinesMap (collision lookup)
    line_cache: LineCellCache,             // shortcut valid until the line grid changes
    lines: IntMap<i32, LineRef>, // id → shared geometry, including its removal footprint
    frames: FrameStates,                        // frames[0] = initial; lazily extended
    events: Vec<Event>,                        // flat per-frame collision records
    event_offsets: Vec<usize>,                 // frame f => events[offset[f]..offset[f+1]]
    summaries: Vec<FrameSummary>, // per-frame compact read summaries for repeated detector windows
    contact_ids: Vec<f64>,        // flat per-frame sled contact line ids used by raw-frame reads
    // Invalidation indexes are materialized lazily, without recharging frames.
    history: CollisionHistory,
    history_events: Vec<Event>, // scratch for lazy history replay
    cur: State,                 // == frames.last() when !cur_dirty; working state for stepping
    cur_dirty: bool, // set on truncation: `cur` is stale, resync from frames.last() before next step
}

impl FrameCache {
    pub(crate) fn new() -> FrameCache {
        let s = init_state(0.0, 0.0, 0.4, 0.0); // DEFAULT_START
        let mut contact_ids = Vec::new();
        let summary = Self::summarize_frame(&s, &[], &mut contact_ids);
        FrameCache {
            cell_lines: FlatIntMap::default(),
            line_cache: LineCellCache::default(),
            lines: IntMap::default(),
            frames: FrameStates::new(s.clone()),
            events: Vec::new(),
            event_offsets: vec![0, 0],
            summaries: vec![summary],
            contact_ids,
            history: CollisionHistory::new(),
            history_events: Vec::new(),
            cur: s,
            cur_dirty: false,
        }
    }

    pub(crate) fn last_frame_index(&self) -> i32 {
        (self.frames.len() - 1) as i32
    }

    /// _setFramesLength(len) — truncate to `len` frames, rolling the history grid +
    /// collisions back via their per-frame reverse patches. lr-core's
    /// `frames.length = index` would GROW the array if `index > length`; that never
    /// happens here (collision indices are recorded frames ≤ the last computed
    /// frame, and rollback drops their records in lockstep), so we only ever
    /// shrink. The debug_assert surfaces a future reconcile path that broke that
    /// invariant instead of silently diverging from JS. `len == 0` is unreachable
    /// (collision indices are ≥ 1) but guarded to avoid a `frames[len-1]` underflow.
    pub(crate) fn set_frames_length(&mut self, len: usize) {
        debug_assert!(
            len <= self.frames.len(),
            "set_frames_length would grow the cache (diverges from lr-core)"
        );
        if len == 0 || len >= self.frames.len() {
            return;
        }
        self.history.truncate(len);
        self.frames.truncate(len);
        self.events.truncate(self.event_offsets[len]);
        self.event_offsets.truncate(len + 1);
        if len < self.summaries.len() {
            self.contact_ids
                .truncate(self.summaries[len].contact_offset);
            self.summaries.truncate(len);
        }
        // Defer the `cur = frames[len-1].clone()` resync: a multi-line arc add
        // truncates many times in a row with no intervening step, so an eager clone
        // here is overwritten by the next truncation before it is ever stepped.
        // Mark stale instead; compute_to resyncs once, only when about to step.
        self.cur_dirty = true;
    }

    /// Geometry registration never simulates between lines. Their invalidations
    /// therefore compose as one minimum over the same history, followed by one
    /// truncation. Preserve insertion order, including repeated line ids.
    pub(crate) fn add_lines(&mut self, lines: &[LineRef]) {
        if !lines.iter().any(|line| line.collidable) { return; }
        self.ensure_history();
        if let Some(first) = self.history.first_for_added_lines(lines, i32::MAX) {
            self.set_frames_length(first as usize);
        }
        self.line_cache.invalidate();
        for line in lines.iter().filter(|line| line.collidable) {
            push_line(&mut self.cell_lines, line, line.cells());
            self.lines.insert(line.id, line.clone());
        }
    }

    /// _removeLine for each id in order: unregister the line, truncate to its
    /// FIRST collision frame. Removing lines never changes recorded collisions,
    /// and successive truncations (with their reverse-patch rollbacks) compose,
    /// so the lines leave the grid in the same order and the cache truncates
    /// once, to the earliest collision with any of them.
    pub(crate) fn remove_lines(&mut self, ids: &[i32], removed: &mut Vec<i32>) {
        if !ids.is_empty() {
            self.line_cache.invalidate();
        }
        removed.clear();
        let mut first: Option<i32> = None;
        for &id in ids {
            if let Some(line) = self.lines.remove(&id) {
                remove_line(&mut self.cell_lines, id, line.cells());
                if let Some(f) = self.history.first_with_line(id) {
                    first = Some(first.map_or(f, |b| b.min(f)));
                }
                removed.push(id);
            }
        }
        // Indexed collisions belong to the tracked prefix, before every frame
        // the event scan could find.
        if first.is_none() && !removed.is_empty() {
            removed.sort_unstable();
            'scan: for f in self.history.len()..self.frames.len() {
                for &(_, line_id, _, _, _) in self.events_at(f) {
                    if removed.binary_search(&line_id).is_ok() {
                        first = Some(f as i32);
                        break 'scan;
                    }
                }
            }
        }
        if let Some(idx) = first {
            self.set_frames_length(idx as usize);
        }
    }

    /// setInitialStates: reset the frame cache to a single frame with a new start
    /// (lines/grid preserved). lr-core: `_setFramesLength(1)` + `frames[0] = new`.
    pub(crate) fn set_initial_states(&mut self, px: f64, py: f64, vx: f64, vy: f64) {
        let s = init_state(px, py, vx, vy);
        self.history.clear();
        self.frames.clear();
        self.frames.push(s.clone());
        self.events.clear();
        self.event_offsets.clear();
        self.event_offsets.extend_from_slice(&[0, 0]);
        self.summaries.clear();
        self.contact_ids.clear();
        let summary = Self::summarize_frame(&s, &[], &mut self.contact_ids);
        self.summaries.push(summary);
        self.history_events.clear();
        self.cur = s;
        self.cur_dirty = false;
    }

    fn ensure_history(&mut self) {
        if self.history.len() >= self.frames.len() {
            return;
        }
        // Replay only the missing suffix with TRACK=true. The public frame/event
        // cache was already produced during the read; this pass fills just the
        // invalidation side indexes without changing simulated-frame accounting.
        let mut s = self.frames[self.history.len() - 1].clone();
        while self.history.len() < self.frames.len() {
            let fi = self.history.len() as i32;
            self.history_events.clear();
            // WASM validation guarantees the solver's SIMD128 requirement.
            unsafe { step_state::<true>(
                &mut s,
                &self.cell_lines,
                &mut self.history_events,
                fi,
                &mut self.history,
                &mut self.line_cache,
                None,
            ); }
            self.history.finish_frame();
        }
    }

    /// _computeFrame: lazily extend the cache to include frame `frame`.
    pub(crate) fn compute_to(&mut self, frame: usize, mut trace: Option<&mut CollisionTrace>) {
        // Resync `cur` from the (possibly truncated) tail once, only when we are
        // actually about to step — see set_frames_length's deferred-resync note.
        if self.frames.len() <= frame && self.cur_dirty {
            self.cur = self.frames[self.frames.len() - 1].clone();
            self.cur_dirty = false;
        }
        while self.frames.len() <= frame {
            let fi = self.frames.len() as i32;
            // WASM validation guarantees the solver's SIMD128 requirement.
            unsafe { step_state::<false>(
                &mut self.cur,
                &self.cell_lines,
                &mut self.events,
                fi,
                &mut self.history,
                &mut self.line_cache,
                trace.as_deref_mut().filter(|trace| trace.frame == fi),
            ); }
            let summary = Self::summarize_frame(
                &self.cur,
                &self.events[self.event_offsets[fi as usize]..],
                &mut self.contact_ids,
            );
            self.frames.push(self.cur.clone());
            self.event_offsets.push(self.events.len());
            self.summaries.push(summary);
        }
    }

    #[inline]
    pub(crate) fn events_at(&self, f: usize) -> &[Event] {
        &self.events[self.event_offsets[f]..self.event_offsets[f + 1]]
    }

    /// Advance one frame at a time, stopping on the first broken binding. This
    /// shares the ordinary stepping path, including collision trace capture.
    pub(crate) fn advance_while_bound(&mut self, frame: usize, mut trace: Option<&mut CollisionTrace>) -> bool {
        while self.frames.len() <= frame {
            let next = self.frames.len();
            self.compute_to(next, trace.as_deref_mut());
            if !self.is_bound(next) { return false; }
        }
        self.is_bound(frame)
    }

    pub(crate) fn is_bound(&self, frame: usize) -> bool {
        let summary = self.summary(frame);
        summary.rider_fsu == -1 && summary.sled_fsu == -1
    }

    pub(crate) fn frame_count(&self) -> usize {
        self.frames.len()
    }
    pub(crate) fn frame(&self, index: usize) -> &State {
        &self.frames[index]
    }
    pub(crate) fn summary(&self, index: usize) -> &FrameSummary {
        &self.summaries[index]
    }
    pub(crate) fn contacts(&self, start: usize, end: usize) -> &[f64] {
        &self.contact_ids[start..end]
    }

    /// Derived once per immutable frame, only when an observer asks for it.
    /// Clone preserves valid memo values; reset and rollback discard old frames.
    pub(crate) fn body_motion(&self, frame: usize) -> &[f64; 4] {
        self.summaries[frame].motion.get_or_init(|| {
            let s = self.frame(frame);
            let (mut cx, mut cy, mut vx, mut vy) = (0.0, 0.0, 0.0, 0.0);
            for i in 2..NENT {
                cx += s.position[i].x;
                cy += s.position[i].y;
                vx += s.position[i].x - s.previous[i].x;
                vy += s.position[i].y - s.previous[i].y;
            }
            cx /= 10.0;
            cy /= 10.0;
            vx /= 10.0;
            vy /= 10.0;
            let (mut momentum, mut radius2) = (0.0, 0.0);
            for i in 2..NENT {
                let rx = s.position[i].x - cx;
                let ry = s.position[i].y - cy;
                momentum += rx * (s.position[i].y - s.previous[i].y - vy) - ry * (s.position[i].x - s.previous[i].x - vx);
                radius2 += rx * rx + ry * ry;
            }
            [vx, vy, momentum, (radius2 / 10.0).sqrt()]
        })
    }

    fn summarize_frame(s: &State, events: &[Event], contact_ids: &mut Vec<f64>) -> FrameSummary {
        let (mut px, mut py, mut vx, mut vy) = (0.0, 0.0, 0.0, 0.0);
        for &entity in BODY.iter() {
            px += s.position[entity].x;
            py += s.position[entity].y;
            vx += s.velocity[entity].x;
            vy += s.velocity[entity].y;
        }
        let n_body = BODY.len() as f64;
        let contact_offset = contact_ids.len();
        let mut sled_mask = 0u32;
        let mut sled_points = [0; 4];
        let mut sled_count = 0;
        for &(_, line_id, point_idx, _, _) in events {
            let bit = 1u32 << (point_idx as u32);
            if (SLED_POINT_MASK & bit) == 0 {
                continue;
            }
            if sled_mask & bit == 0 {
                sled_points[sled_count] = point_idx as u8;
                sled_count += 1;
                sled_mask |= bit;
            }
            let line_id = line_id as f64;
            let mut seen_line = false;
            for &seen in contact_ids[contact_offset..].iter() {
                if seen == line_id {
                    seen_line = true;
                    break;
                }
            }
            if !seen_line {
                contact_ids.push(line_id);
            }
        }
        FrameSummary {
            body_px: px / n_body,
            body_py: py / n_body,
            body_vx: vx / n_body,
            body_vy: vy / n_body,
            rider_fsu: s.fsu[RIDER_MOUNTED],
            sled_fsu: s.fsu[SLED_INTACT],
            sled_points,
            sled_count: sled_count as u8,
            motion: OnceCell::new(),
            contact_offset,
            contact_count: contact_ids.len() - contact_offset,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::line::build_line;

    #[test]
    fn batched_registration_matches_ordered_single_edits_and_future_replay() {
        let mut base = FrameCache::new();
        base.set_initial_states(0.0, -15.0, 8.0, 0.0);
        base.add_lines(&[build_line(1, -50.0, 10.0, 800.0, 10.0, 0, 0)]);
        base.compute_to(80, None);
        for trial in 0..80 {
            let lines: Vec<_> = (0..24).map(|i| {
                let x = ((i * 31 + trial * 11) % 240 - 50) as f64;
                let y = ((i * 13 + trial * 17) % 60 - 30) as f64;
                build_line(2 + i % 19, x, y, x + 20.0, y + (trial % 5 - 2) as f64 * 10.0,
                    (i % 3) as i64, (trial % 8) as i64)
            }).collect();
            let mut batch = base.clone();
            let mut scalar = base.clone();
            batch.add_lines(&lines);
            for line in &lines { scalar.add_lines(std::slice::from_ref(line)); }
            assert_eq!(batch.last_frame_index(), scalar.last_frame_index());
            batch.compute_to(100, None);
            scalar.compute_to(100, None);
            for frame in 0..=100 {
                let a = batch.frame(frame);
                let b = scalar.frame(frame);
                for (a, b) in [(&a.position, &b.position), (&a.previous, &b.previous), (&a.velocity, &b.velocity)] {
                    for (a, b) in a.iter().zip(b.iter()) {
                        assert_eq!(a.x.to_bits(), b.x.to_bits());
                        assert_eq!(a.y.to_bits(), b.y.to_bits());
                    }
                }
                assert_eq!(a.fsu, b.fsu);
                assert_eq!(batch.events_at(frame), scalar.events_at(frame));
            }
            let probe = [build_line(90, 0.0, 5.0, 120.0, 10.0, 0, 0)];
            batch.add_lines(&probe);
            scalar.add_lines(&probe);
            assert_eq!(batch.last_frame_index(), scalar.last_frame_index());
        }
    }
}

//! Immutable version handles over lineage-local frame caches. Reads reconcile
//! the cache through the version tree before observing or extending it. This
//! preserves lr-core's path-dependent frame budget, including sibling reads.
//! Handles, ancestry and optional solver observations have one arena owner.

use crate::cache::{FrameCache, FrameSummary};
use crate::kernel::CollisionTrace;
#[cfg(test)]
use crate::line::build_line;
use crate::line::LineRef;
use crate::{NENT, NOSE, PEG, STRING, TAIL};
use std::{cell::RefCell, rc::Rc};

pub(crate) const RAW_FRAME_STRIDE: usize = 13;

// ── version tree (each engine handle is a node) + per-lineage cache ──
enum Patch {
    Root,
    SetStart,
    /// One addLine batch, in insertion order. A batch is one version: lr-core's
    /// addLine([l1..ln]) applies its lines with no read in between.
    AddLines(Vec<LineRef>),
}

struct Version {
    lineage: u32,
    parent: i32, // -1 for root
    depth: u32,
    patch: Patch,
    start: [f64; 4],
    start_generation: u32, // initialStateMap identity (bumped on SetStart)
    freed: bool,           // the external handle no longer owns this version
    trace: Option<Box<CollisionTrace>>, // observation belongs to this version, never its siblings
    children: u32,         // direct descendants that still need this patch as ancestry
}

struct Lineage {
    // Detached lineages share an immutable snapshot until one needs to write.
    // Releasing the source first transfers the cache without cloning its data.
    cache: Rc<FrameCache>,
    current: i32,          // version the cache is currently synced to
    live: u32,             // handles in this lineage whose JS wrapper hasn't been freed
    version_ids: Vec<u32>, // reserved slots, including reclaimed nodes; reusable at lineage death
}

// One owner for version slots, lineage caches and reusable reconciliation scratch.
// An operation borrows it for the whole ABI call; no references escape that scope.
// RefCell enforces the non-reentrant boundary instead of relying on static-mut
// aliases. The WASM instance is single-threaded; native test threads own arenas.
pub(crate) struct EngineArena {
    versions: Vec<Option<Box<Version>>>,
    lineages: Vec<Option<Lineage>>,
    free_versions: Vec<u32>,
    free_lineages: Vec<u32>,
    generation: u32,
    undo: Vec<i32>,
    redo: Vec<LineRef>,
    removed: Vec<i32>,
}

impl EngineArena {
    const fn new() -> Self {
        Self {
            versions: Vec::new(),
            lineages: Vec::new(),
            free_versions: Vec::new(),
            free_lineages: Vec::new(),
            generation: 0,
            undo: Vec::new(),
            redo: Vec::new(),
            removed: Vec::new(),
        }
    }

    fn next_generation(&mut self) -> u32 {
        self.generation += 1;
        self.generation
    }
    fn valid(&self, h: u32) -> bool {
        matches!(self.versions.get(h as usize), Some(Some(_)))
    }
    fn ver(&self, id: i32) -> &Version {
        self.versions[id as usize].as_ref().unwrap()
    }

    fn alloc_version(&mut self, v: Version) -> u32 {
        if v.parent >= 0 {
            self.versions[v.parent as usize].as_mut().unwrap().children += 1;
        }
        if let Some(id) = self.free_versions.pop() {
            self.versions[id as usize] = Some(Box::new(v));
            id
        } else {
            self.versions.push(Some(Box::new(v)));
            (self.versions.len() - 1) as u32
        }
    }

    /// new LineRiderEngine(): a fresh lineage (lineage + root version).
    pub(crate) fn create(&mut self) -> u32 {
        let lineage = if let Some(id) = self.free_lineages.pop() {
            id
        } else {
            self.lineages.push(None);
            (self.lineages.len() - 1) as u32
        };
        let vid = self.alloc_version(Version {
            lineage,
            parent: -1,
            depth: 0,
            patch: Patch::Root,
            start: [0.0, 0.0, 0.4, 0.0],
            start_generation: 0,
            freed: false,
            trace: None,
            children: 0,
        });
        self.lineages[lineage as usize] = Some(Lineage {
            cache: Rc::new(FrameCache::new()),
            current: vid as i32,
            live: 1,
            version_ids: vec![vid],
        });
        vid
    }

    /// setStart: sync the cache to `h`, reset it to a single frame with the new start,
    /// and create a new version with a fresh initialStateMap identity.
    pub(crate) fn set_start(&mut self, h: u32, px: f64, py: f64, vx: f64, vy: f64) -> u32 {
        self.update_computed(h);
        let (lineage, parent_depth) = {
            let p = self.ver(h as i32);
            (p.lineage, p.depth)
        };
        let g = self.next_generation();
        let vid = self.alloc_version(Version {
            lineage,
            parent: h as i32,
            depth: parent_depth + 1,
            patch: Patch::SetStart,
            start: [px, py, vx, vy],
            start_generation: g,
            freed: false,
            trace: None,
            children: 0,
        });
        let hh = self.lineages[lineage as usize].as_mut().unwrap();
        Rc::make_mut(&mut hh.cache).set_initial_states(px, py, vx, vy);
        hh.current = vid as i32;
        hh.live += 1;
        hh.version_ids.push(vid);
        vid
    }

    /// addLine: sync the cache to `h`, add the line to the shared cache, create a new
    /// version (AddLines patch) that becomes the cache's current.
    #[cfg(test)]
    fn add_line(
        &mut self,
        h: u32,
        id: i32,
        ty: i32,
        x1: f64,
        y1: f64,
        x2: f64,
        y2: f64,
        flags: i32,
    ) -> u32 {
        self.add_lines(
            h,
            vec![build_line(id, x1, y1, x2, y2, ty as i64, flags as i64)],
        )
    }

    /// addLine([l1..ln]): sync the cache to `h`, add each line to the shared cache in
    /// order, and create one version (AddLines patch) that becomes the cache's current.
    /// The cache sees the same _addLine sequence as n single-line versions would.
    pub(crate) fn add_lines(&mut self, h: u32, lines: Vec<LineRef>) -> u32 {
        self.update_computed(h);
        let (lineage, parent_depth, start, start_generation) = {
            let p = self.ver(h as i32);
            (p.lineage, p.depth, p.start, p.start_generation)
        };
        let hh = self.lineages[lineage as usize].as_mut().unwrap();
        let cache = Rc::make_mut(&mut hh.cache);
        cache.add_lines(&lines);
        let vid = self.alloc_version(Version {
            lineage,
            parent: h as i32,
            depth: parent_depth + 1,
            patch: Patch::AddLines(lines),
            start,
            start_generation,
            freed: false,
            trace: None,
            children: 0,
        });
        let hh = self.lineages[lineage as usize].as_mut().unwrap();
        hh.current = vid as i32;
        hh.live += 1;
        hh.version_ids.push(vid);
        vid
    }

    /// free a handle: mark its version freed and drop the lineage's live count; when no
    /// live handle remains, reclaim the whole lineage (its cache + all version slots).
    pub(crate) fn free(&mut self, h: u32) {
        if !self.valid(h) {
            return;
        }
        let lineage_id = {
            let v = self.versions[h as usize].as_mut().unwrap();
            if v.freed {
                return; // already freed
            }
            v.freed = true;
            v.trace = None;
            v.lineage
        };
        let hh = self.lineages[lineage_id as usize].as_mut().unwrap();
        hh.live -= 1;
        if hh.live == 0 {
            let dead = self.lineages[lineage_id as usize].take().unwrap(); // releases this lineage's cache ownership
            for vid in dead.version_ids {
                self.versions[vid as usize] = None;
                self.free_versions.push(vid);
            }
            self.free_lineages.push(lineage_id);
        } else {
            self.reclaim_unused(h as i32);
        }
    }

    /// A released leaf can be discarded once the cache no longer needs its patch.
    /// Unwind its unowned ancestors too. The slot stays reserved in version_ids
    /// until lineage death, so stale handles cannot alias a newly allocated node.
    fn reclaim_unused(&mut self, mut id: i32) {
        while id >= 0 {
            let v = self.ver(id);
            if !v.freed
                || v.children > 0
                || self.lineages[v.lineage as usize].as_ref().unwrap().current == id
            {
                break;
            }
            let parent = v.parent;
            self.versions[id as usize] = None;
            if parent >= 0 {
                let p = self.versions[parent as usize].as_mut().unwrap();
                assert!(p.children > 0);
                p.children -= 1;
            }
            id = parent;
        }
    }

    /// updateComputed: reconcile the shared cache from its current version to `target`
    /// by walking the patch tree (undo current's AddLines to the LCA, redo target's),
    /// then resetting the start if the initialStateMap identity differs.
    ///
    /// Immo reconciles three state members; here only two can ever differ: linesList
    /// (the patch walk) and initialStateMap (start_generation). The third, `constraints`, is
    /// baked as immutable rider const tables (lib.rs) — there is no ABI to change them
    /// — so it is constant across every version and needs no reconcile.
    fn update_computed(&mut self, target: u32) {
        let target = target as i32;
        let lineage = self.ver(target).lineage;
        let current = self.lineages[lineage as usize].as_ref().unwrap().current;
        if current == target {
            // Preparation already evicts this version's pending trace. Only a
            // sibling can refill that prefix, which changes the current version.
            return;
        }

        // Walk to the LCA, collecting line ops (Immy.List.compareTo over a shared root).
        // Only AddLines patches carry lines (Root/SetStart carry none), so undo is
        // purely removes and redo purely adds. A batch's lines are collected most
        // recent first, like single-line versions. Scratch buffers are reused across calls
        // (cleared here, drained below) to avoid a per-reconcile Vec allocation.
        let versions = &self.versions;
        let ver = |id: i32| versions[id as usize].as_ref().unwrap();
        let undo_ids = &mut self.undo;
        let redo_lines = &mut self.redo;
        undo_ids.clear();
        redo_lines.clear();
        let mut a = current;
        let mut b = target;
        while ver(a).depth > ver(b).depth {
            if let Patch::AddLines(ls) = &ver(a).patch {
                undo_ids.extend(ls.iter().rev().map(|l| l.id));
            }
            a = ver(a).parent;
        }
        while ver(b).depth > ver(a).depth {
            if let Patch::AddLines(ls) = &ver(b).patch {
                redo_lines.extend(ls.iter().rev().cloned());
            }
            b = ver(b).parent;
        }
        while a != b {
            if let Patch::AddLines(ls) = &ver(a).patch {
                undo_ids.extend(ls.iter().rev().map(|l| l.id));
            }
            a = ver(a).parent;
            if let Patch::AddLines(ls) = &ver(b).patch {
                redo_lines.extend(ls.iter().rev().cloned());
            }
            b = ver(b).parent;
        }
        redo_lines.reverse(); // oldest-first

        let start_changed = ver(current).start_generation != ver(target).start_generation;
        let target_start = ver(target).start;

        let cache = Rc::make_mut(&mut self.lineages[lineage as usize].as_mut().unwrap().cache);
        // Reconcile geometry before the initial state, retaining scratch capacity.
        cache.remove_lines(undo_ids, &mut self.removed);
        cache.add_lines(redo_lines);
        redo_lines.clear();
        // initialStateMap reconcile: a SetStart somewhere between the two versions.
        if start_changed {
            cache.set_initial_states(
                target_start[0],
                target_start[1],
                target_start[2],
                target_start[3],
            );
        }
        self.lineages[lineage as usize].as_mut().unwrap().current = target;
        self.reclaim_unused(current);
        self.evict_pending_trace(target as u32);
    }

    // A sibling may have filled the shared cache since this trace was requested.
    // Evict before reporting the available prefix so metered readers charge replay.
    fn evict_pending_trace(&mut self, handle: u32) {
        let version = self.versions[handle as usize].as_ref().unwrap();
        if let Some(trace) = &version.trace {
            if trace.count == 0 {
                let cache = &mut self.lineages[version.lineage as usize]
                    .as_mut()
                    .unwrap()
                    .cache;
                if cache.frame_count() > trace.frame as usize {
                    Rc::make_mut(cache).set_frames_length(trace.frame as usize);
                }
            }
        }
    }

    // Every computing read reconciles and supplies only this version's trace.
    fn frame_cache(&mut self, handle: u32, frame: i32) -> Option<&FrameCache> {
        if frame < 0 || !self.valid(handle) {
            return None;
        }
        self.update_computed(handle);
        let lineage = self.ver(handle as i32).lineage;
        let cache = &mut self.lineages[lineage as usize].as_mut().unwrap().cache;
        if cache.frame_count() <= frame as usize {
            let trace = self.versions[handle as usize]
                .as_mut()
                .unwrap()
                .trace
                .as_deref_mut()
                .filter(|trace| trace.count == 0);
            Rc::make_mut(cache).compute_to(frame as usize, trace);
        }
        Some(cache)
    }

    // Observations reconcile the version but never extend its frame cache.
    fn cached_frame_cache(&mut self, handle: u32, frame: i32) -> Option<&FrameCache> {
        if frame < 0 || !self.valid(handle) {
            return None;
        }
        self.update_computed(handle);
        let cache = &self.lineages[self.ver(handle as i32).lineage as usize]
            .as_ref()
            .unwrap()
            .cache;
        (frame <= cache.last_frame_index()).then_some(cache)
    }

    /// One native call for a bounded replay. The caller chooses an affordable
    /// horizon and charges the actual cache extension, including early failure.
    pub(crate) fn advance_while_bound(&mut self, handle: u32, frame: i32) -> bool {
        if frame < 0 || !self.valid(handle) { return false; }
        self.update_computed(handle);
        let lineage = self.ver(handle as i32).lineage;
        let cache = &mut self.lineages[lineage as usize].as_mut().unwrap().cache;
        if cache.frame_count() > frame as usize { return cache.is_bound(frame as usize); }
        let trace = self.versions[handle as usize].as_mut().unwrap().trace.as_deref_mut()
            .filter(|trace| trace.count == 0);
        Rc::make_mut(cache).advance_while_bound(frame as usize, trace)
    }

    /// Whole-body motion, in the same point and arithmetic order as bodyMotion()
    /// in strike_impact.ts. Check and observe in one call; never simulate.
    pub(crate) fn body_motion_into(&mut self, handle: u32, frame: i32, out: &mut [f64]) -> bool {
        let Some(cache) = self.cached_frame_cache(handle, frame) else {
            return false;
        };
        out[..4].copy_from_slice(cache.body_motion(frame as usize));
        true
    }

    /// Packed cached-only [vx, vy, angular momentum, radius, contact] per frame.
    pub(crate) fn motion_window_into(
        &mut self,
        handle: u32,
        start: i32,
        end: i32,
        out: &mut Vec<f64>,
    ) -> bool {
        if start < 0 || end < start {
            return false;
        }
        let Some(cache) = self.cached_frame_cache(handle, end) else {
            return false;
        };
        out.clear();
        out.reserve((end - start + 1) as usize * 5);
        for frame in start as usize..=end as usize {
            out.extend_from_slice(cache.body_motion(frame));
            out.push((!cache.events_at(frame).is_empty()) as u8 as f64);
        }
        true
    }

    pub(crate) fn collision_trace_into(&self, handle: u32, out: &mut [f64]) -> usize {
        let Some(version) = self.versions.get(handle as usize).and_then(Option::as_ref) else {
            return 0;
        };
        let Some(trace) = &version.trace else {
            return 0;
        };
        out[..trace.points.len()].copy_from_slice(&trace.points);
        trace.count
    }

    pub(crate) fn last_frame_index(&mut self, h: u32) -> i32 {
        if !self.valid(h) {
            return -1;
        }
        self.update_computed(h);
        let lineage = self.ver(h as i32).lineage;
        self.lineages[lineage as usize]
            .as_ref()
            .unwrap()
            .cache
            .last_frame_index()
    }

    /// Compute (if needed) frame `f` of version `h` and write it into `out`:
    /// 12 entities × [px,py,prevx,prevy,vx,vy] (72 f64), then 12 fsu. No-op (leaves
    /// `out` untouched) on an invalid handle or negative frame. The typed wrapper
    /// rejects invalid reads before entering this private ABI.
    pub(crate) fn state_into(&mut self, h: u32, f: i32, out: &mut [f64]) {
        let Some(cache) = self.frame_cache(h, f) else {
            return;
        };
        let f = f as usize;
        let s = cache.frame(f);
        for i in 0..NENT {
            let o = i * 6;
            out[o] = s.position[i].x;
            out[o + 1] = s.position[i].y;
            out[o + 2] = s.previous[i].x;
            out[o + 3] = s.previous[i].y;
            out[o + 4] = s.velocity[i].x;
            out[o + 5] = s.velocity[i].y;
        }
        for i in 0..NENT {
            out[NENT * 6 + i] = s.fsu[i] as f64;
        }
    }

    /// getRider, computed in Rust to avoid rebuilding the JS stateMap on the hot path.
    /// Writes 6 f64: avg BODY pos.x/y, avg BODY vel.x/y (summed in BODY order then /6
    /// — bit-identical to Rider.getBody), then the RIDER_MOUNTED and SLED_INTACT fsu
    /// (the only two bindings the detector reads via rider.get(id).isBinded()).
    pub(crate) fn rider_into(&mut self, h: u32, f: i32, out: &mut [f64]) {
        let Some(cache) = self.frame_cache(h, f) else {
            return;
        };
        let f = f as usize;
        let s = cache.frame(f);
        let summary = cache.summary(f);
        out[0] = summary.body_px;
        out[1] = summary.body_py;
        out[2] = summary.body_vx;
        out[3] = summary.body_vy;
        out[4] = summary.rider_fsu as f64;
        out[5] = summary.sled_fsu as f64;
        // Slots 6..29: PEG/TAIL/NOSE/STRING point states as 4 × [px,py,prevx,prevy,vx,vy].
        // These are the only point ids the compiler probes through getRider on the WASM
        // path; keeping them in the lean payload avoids the cold full-stateMap fallback.
        for (k, &i) in [PEG, TAIL, NOSE, STRING].iter().enumerate() {
            let o = 6 + k * 6;
            out[o] = s.position[i].x;
            out[o + 1] = s.position[i].y;
            out[o + 2] = s.previous[i].x;
            out[o + 3] = s.previous[i].y;
            out[o + 4] = s.velocity[i].x;
            out[o + 5] = s.velocity[i].y;
        }
    }

    /// Read all ordered collisions; the transport buffer retains its allocation.
    pub(crate) fn events_into(&mut self, h: u32, f: i32, out: &mut Vec<f64>) -> usize {
        let Some(cache) = self.frame_cache(h, f) else {
            return 0;
        };
        write_events(cache.events_at(f as usize), out)
    }

    pub(crate) fn cached_events_into(
        &mut self,
        h: u32,
        f: i32,
        out: &mut Vec<f64>,
    ) -> Option<usize> {
        let cache = self.cached_frame_cache(h, f)?;
        Some(write_events(cache.events_at(f as usize), out))
    }

    pub(crate) fn has_contact(&mut self, h: u32, f: i32) -> Option<bool> {
        let cache = self.cached_frame_cache(h, f)?;
        Some(!cache.events_at(f as usize).is_empty())
    }

    /// Combined detector hot path: compute frame `f` once, then write the getRider
    /// summary and first-contact point order to `scratch`, and the already
    /// deduplicated contact line ids to `contacts`. Never rebuild a cached summary.
    pub(crate) fn raw_frame_into(
        &mut self,
        h: u32,
        f: i32,
        scratch: &mut [f64],
        contacts: &mut Vec<f64>,
    ) -> usize {
        let Some(cache) = self.frame_cache(h, f) else {
            return 0;
        };
        let f = f as usize;
        let summary = cache.summary(f);
        write_raw_summary(summary, scratch);
        let count = summary.contact_count;
        grow_output(contacts, count);
        contacts[..count].copy_from_slice(
            cache.contacts(summary.contact_offset, summary.contact_offset + count),
        );
        count
    }

    /// Cached raw frames: the scalar payload, followed by contact offset/count.
    /// Read the complete window in one arena borrow without advancing physics.
    pub(crate) fn raw_window_into(
        &mut self,
        h: u32,
        start: i32,
        end: i32,
        out: &mut Vec<f64>,
        contacts: &mut Vec<f64>,
    ) -> i32 {
        if start < 0 || end < start {
            return -1;
        }
        let Some(cache) = self.cached_frame_cache(h, end) else {
            return -1;
        };
        let first_contact = cache.summary(start as usize).contact_offset;
        let last = cache.summary(end as usize);
        let contact_count = last.contact_offset + last.contact_count - first_contact;
        contacts.clear();
        contacts.extend_from_slice(cache.contacts(first_contact, first_contact + contact_count));
        let frame_count = (end - start + 1) as usize;
        grow_output(out, frame_count * RAW_FRAME_STRIDE);
        for i in 0..frame_count {
            let summary = cache.summary(start as usize + i);
            let row = &mut out[i * RAW_FRAME_STRIDE..(i + 1) * RAW_FRAME_STRIDE];
            write_raw_summary(summary, row);
            row[11] = (summary.contact_offset - first_contact) as f64;
            row[12] = summary.contact_count as f64;
        }
        contact_count as i32
    }

    /// Detach an already-computed immutable prefix into an independent lineage.
    /// Share its backing cache until a write; no stepping or new initial state.
    /// FrameCache::clone resets borrowed line queries when copy-on-write is necessary.
    pub(crate) fn detach(&mut self, h: u32) -> u32 {
        self.update_computed(h);
        let (cache, start, start_generation) = {
            let v = self.ver(h as i32);
            (
                self.lineages[v.lineage as usize]
                    .as_ref()
                    .unwrap()
                    .cache
                    .clone(),
                v.start,
                v.start_generation,
            )
        };
        let lineage = if let Some(id) = self.free_lineages.pop() {
            id
        } else {
            self.lineages.push(None);
            (self.lineages.len() - 1) as u32
        };
        let vid = self.alloc_version(Version {
            lineage,
            parent: -1,
            depth: 0,
            patch: Patch::Root,
            start,
            start_generation,
            freed: false,
            trace: None,
            children: 0,
        });
        self.lineages[lineage as usize] = Some(Lineage {
            cache,
            current: vid as i32,
            live: 1,
            version_ids: vec![vid],
        });
        vid
    }

    /// Evict the requested frame so a subsequent metered read records its solver
    /// states. This API performs no stepping: the caller charges the actual replay.
    pub(crate) fn prepare_collision_trace(&mut self, h: u32, frame: i32) {
        assert!(frame > 0);
        self.update_computed(h);
        let lineage = self.ver(h as i32).lineage;
        let cache = &mut self.lineages[lineage as usize].as_mut().unwrap().cache;
        if cache.frame_count() > frame as usize {
            Rc::make_mut(cache).set_frames_length(frame as usize);
        }
        let trace = &mut self.versions[h as usize].as_mut().unwrap().trace;
        if let Some(trace) = trace {
            trace.reset(frame);
        } else {
            *trace = Some(Box::new(CollisionTrace::new(frame)));
        }
    }

    /// Read only already-computed collision positions. A missing window is an error,
    /// never an implicit unmetered simulation. Branch invalidation applies normally.
    pub(crate) fn contact_positions(
        &mut self,
        h: u32,
        start: i32,
        end: i32,
        out: &mut Vec<f64>,
    ) -> bool {
        out.clear();
        if start < 0 || end < start {
            return false;
        }
        let Some(cache) = self.cached_frame_cache(h, end) else {
            return false;
        };
        for f in start as usize..=end as usize {
            for &(_, id, _, x, y) in cache.events_at(f) {
                out.extend_from_slice(&[id as f64, x, y]);
            }
        }
        true
    }
}

// Transport buffers retain their initialized high-water prefix. Only the count
// returned by the read is logical output; no per-entry capacity checks or caps.
fn grow_output(out: &mut Vec<f64>, needed: usize) {
    if out.len() < needed {
        out.resize(needed, 0.0);
    }
}

fn write_events(events: &[crate::kernel::Collision], out: &mut Vec<f64>) -> usize {
    grow_output(out, events.len() * 3);
    for (record, &(iteration, line, point, _, _)) in out.chunks_exact_mut(3).zip(events) {
        record[0] = iteration as f64;
        record[1] = line as f64;
        record[2] = point as f64;
    }
    events.len()
}

fn write_raw_summary(summary: &FrameSummary, out: &mut [f64]) {
    out[..7].copy_from_slice(&[
        summary.body_px,
        summary.body_py,
        summary.body_vx,
        summary.body_vy,
        summary.rider_fsu as f64,
        summary.sled_fsu as f64,
        summary.sled_count as f64,
    ]);
    for (i, point) in summary.sled_points[..summary.sled_count as usize]
        .iter()
        .enumerate()
    {
        out[7 + i] = *point as f64;
    }
}

thread_local! {
    static ARENA: RefCell<EngineArena> = const { RefCell::new(EngineArena::new()) };
}

pub(crate) fn with_arena<R>(operation: impl FnOnce(&mut EngineArena) -> R) -> R {
    ARENA.with(|arena| operation(&mut arena.borrow_mut()))
}

#[cfg(test)]
mod ownership_tests {
    use super::*;
    #[test]
    fn arena_scope_rejects_reentry_and_releases_its_borrow_after_unwind() {
        let handle = with_arena(|arena| arena.create());
        let nested = std::panic::catch_unwind(|| {
            with_arena(|_| with_arena(|arena| arena.last_frame_index(handle)))
        });
        assert!(nested.is_err());
        with_arena(|arena| {
            assert_eq!(arena.last_frame_index(handle), 0);
            arena.free(handle);
        });
    }

    #[test]
    fn independently_owned_arenas_do_not_share_handles_or_reconciliation() {
        let mut left = EngineArena::new();
        let mut right = EngineArena::new();
        let a = left.create();
        let b = right.create();
        assert_eq!(a, b); // ids are local to an arena
        let child = left.set_start(a, 10.0, -25.0, 2.0, 1.0);
        left.free(a);
        assert_eq!(right.last_frame_index(b), 0);
        let mut state = [0.0; 84];
        left.state_into(child, 20, &mut state);
        assert_eq!(left.last_frame_index(child), 20);
        assert_eq!(right.last_frame_index(b), 0);
        left.free(child);
        assert!(right.valid(b));
        right.free(b);
    }

    #[test]
    fn event_output_keeps_every_record_past_the_former_capacity() {
        let events: Vec<_> = (0..20_000)
            .map(|i| ((i % 6) as u8, i, i % 12, 1.0, 2.0))
            .collect();
        let mut output = Vec::new();
        assert_eq!(write_events(&events, &mut output), 20_000);
        assert_eq!(output.len(), 60_000);
        for (i, record) in output.chunks_exact(3).enumerate() {
            assert_eq!(record, &[(i % 6) as f64, i as f64, (i % 12) as f64]);
        }
        let allocation = output.as_ptr();
        assert_eq!(write_events(&events[..2], &mut output), 2);
        assert_eq!(output.as_ptr(), allocation);
        assert_eq!(&output[..6], &[0.0, 0.0, 0.0, 1.0, 1.0, 1.0]);
        assert_eq!(write_events(&[], &mut output), 0);
        assert_eq!(output.as_ptr(), allocation);
    }

    #[test]
    fn traces_belong_to_versions_and_pending_sibling_replay_is_visible() {
        let mut arena = EngineArena::new();
        let base = arena.create();
        let sibling = arena.add_line(base, 7, 0, 10000.0, 10000.0, 11000.0, 10000.0, 0);
        let unrelated = arena.create();
        arena.prepare_collision_trace(base, 4);
        arena.prepare_collision_trace(sibling, 4);
        arena.prepare_collision_trace(unrelated, 4);
        let mut state = [0.0; 84];
        let mut trace = [0.0; crate::ITERATE * NENT * 6];
        arena.state_into(base, 4, &mut state);
        assert_eq!(arena.collision_trace_into(base, &mut trace), 6);
        let expected = trace;
        assert_eq!(arena.collision_trace_into(sibling, &mut trace), 0);
        assert_eq!(arena.collision_trace_into(unrelated, &mut trace), 0);
        assert_eq!(
            arena.last_frame_index(sibling),
            3,
            "pending trace exposes replay cost before a metered read"
        );
        arena.state_into(sibling, 4, &mut state);
        assert_eq!(arena.collision_trace_into(sibling, &mut trace), 6);
        assert_eq!(trace, expected);
        arena.state_into(unrelated, 10, &mut state);
        assert_eq!(arena.collision_trace_into(base, &mut trace), 6);
        assert_eq!(
            trace, expected,
            "another lineage must not overwrite an observation"
        );
        let child = arena.add_line(base, 8, 0, 12000.0, 10000.0, 13000.0, 10000.0, 0);
        assert_eq!(
            arena.collision_trace_into(child, &mut trace),
            0,
            "children do not inherit observations"
        );
        assert_eq!(arena.collision_trace_into(base, &mut trace), 6);
        assert_eq!(
            trace, expected,
            "lazy history replay must not record observations"
        );
        arena.free(base);
        assert_eq!(
            arena.collision_trace_into(base, &mut trace),
            0,
            "releasing a version releases its observation"
        );
    }

    #[test]
    fn released_branches_preserve_live_descendants_and_cache_ancestry() {
        let mut arena = EngineArena::new();
        let unrelated = arena.create();
        let root = arena.create();
        let start = arena.set_start(root, 0.0, -15.0, 4.0, 0.0);
        arena.free(root);
        let base = arena.add_line(start, 1, 0, -50.0, 10.0, 400.0, 10.0, 0);
        arena.free(start);
        let mut expected = [0.0; 84];
        arena.state_into(base, 40, &mut expected);
        let branch = arena.add_line(base, 2, 0, 600.0, 10.0, 700.0, 10.0, 0);
        arena.free(branch);
        assert!(
            arena.valid(branch),
            "cache current still needs its ancestry"
        );
        arena.last_frame_index(base);
        assert!(
            !arena.valid(branch),
            "released branch should be reclaimed after reconcile"
        );
        let mut actual = [0.0; 84];
        arena.state_into(base, 40, &mut actual);
        assert_eq!(actual, expected);
        let parent = arena.add_line(base, 3, 0, 600.0, 10.0, 700.0, 10.0, 0);
        assert_ne!(
            parent, branch,
            "dead slots cannot be reused inside a live lineage"
        );
        let leaf = arena.add_line(parent, 4, 0, 700.0, 10.0, 800.0, 10.0, 0);
        arena.free(parent);
        assert!(arena.valid(parent), "live child owns ancestry");
        arena.last_frame_index(base);
        assert!(arena.valid(parent));
        arena.state_into(leaf, 40, &mut actual);
        assert_eq!(actual, expected);
        arena.free(leaf);
        assert!(arena.valid(leaf), "cache still owns this branch");
        arena.last_frame_index(base);
        assert!(!arena.valid(leaf));
        assert!(!arena.valid(parent));
        arena.state_into(base, 40, &mut actual);
        assert_eq!(actual, expected);
        arena.free(base);
        assert!(!arena.valid(base));
        assert!(!arena.valid(root));
        assert!(!arena.valid(start));
        assert_eq!(
            arena.last_frame_index(unrelated),
            0,
            "other lineage is caller-owned"
        );
        arena.free(unrelated);
    }

    #[test]
    fn detached_prefixes_isolate_reads_edits_trace_eviction_and_released_sources() {
        let mut arena = EngineArena::new();
        let root = arena.create();
        let start = arena.set_start(root, 0.0, -15.0, 4.0, 0.0);
        arena.free(root);
        let base = arena.add_line(start, 1, 0, -50.0, 10.0, 800.0, 10.0, 0);
        arena.free(start);
        let mut at60 = [0.0; 84];
        arena.state_into(base, 60, &mut at60);
        let detached = arena.detach(base);
        let mut actual = [0.0; 84];
        arena.state_into(detached, 60, &mut actual);
        assert_eq!(actual, at60);
        let mut at100 = [0.0; 84];
        arena.state_into(detached, 100, &mut at100);
        assert_eq!(
            arena.last_frame_index(base),
            60,
            "extending a detached prefix must not extend its source"
        );
        arena.state_into(base, 60, &mut actual);
        assert_eq!(actual, at60);
        arena.state_into(base, 100, &mut actual);
        assert_eq!(actual, at100);
        let edited = arena.add_line(base, 2, 0, -50.0, 8.0, 800.0, 8.0, 0);
        arena.state_into(edited, 100, &mut actual);
        assert_ne!(actual, at100);
        assert_eq!(arena.last_frame_index(detached), 100);
        arena.state_into(detached, 100, &mut actual);
        assert_eq!(actual, at100);
        arena.prepare_collision_trace(detached, 40);
        assert_eq!(arena.last_frame_index(detached), 39);
        assert_eq!(
            arena.last_frame_index(edited),
            100,
            "trace eviction belongs only to its lineage"
        );
        arena.state_into(detached, 100, &mut actual);
        assert_eq!(actual, at100);
        let reset = arena.set_start(detached, 10.0, -25.0, 2.0, 1.0);
        assert_eq!(arena.last_frame_index(reset), 0);
        assert_eq!(arena.last_frame_index(edited), 100);
        arena.state_into(detached, 100, &mut actual);
        assert_eq!(actual, at100);
        let mut expected = [0.0; 84];
        arena.state_into(detached, 120, &mut expected);
        let transferred = arena.detach(detached);
        arena.free(reset);
        arena.free(detached);
        arena.free(edited);
        arena.free(base);
        arena.state_into(transferred, 120, &mut actual);
        assert_eq!(actual, expected);
        arena.state_into(transferred, 140, &mut actual);
        assert_eq!(arena.last_frame_index(transferred), 140);
        arena.free(transferred);
    }
}

//! Saved physics states share immutable chunks across detached engine caches.
//! Truncation changes the visible prefix; only an appended partial chunk needs
//! copying. The solver's mutable working state remains outside this store.

use crate::kernel::State;
use std::{ops::Index, rc::Rc};

const CHUNK_FRAMES: usize = 64;

#[derive(Clone, Default)]
pub(crate) struct FrameStates {
    chunks: Vec<Rc<Vec<State>>>,
    len: usize,
}

impl FrameStates {
    pub(crate) fn new(initial: State) -> Self {
        let mut states = Self::default();
        states.push(initial);
        states
    }

    pub(crate) fn len(&self) -> usize { self.len }

    pub(crate) fn clear(&mut self) {
        self.chunks.clear();
        self.len = 0;
    }

    pub(crate) fn truncate(&mut self, len: usize) {
        if len >= self.len { return; }
        self.chunks.truncate(len.div_ceil(CHUNK_FRAMES));
        self.len = len;
    }

    pub(crate) fn push(&mut self, state: State) {
        let offset = self.len % CHUNK_FRAMES;
        if offset == 0 {
            self.chunks.push(Rc::new(Vec::with_capacity(CHUNK_FRAMES)));
        }
        let tail = Rc::make_mut(self.chunks.last_mut().unwrap());
        tail.truncate(offset);
        tail.push(state);
        self.len += 1;
    }
}

impl Index<usize> for FrameStates {
    type Output = State;
    fn index(&self, index: usize) -> &State {
        assert!(index < self.len, "frame outside the saved prefix");
        &self.chunks[index / CHUNK_FRAMES][index % CHUNK_FRAMES]
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::kernel::init_state;

    #[test]
    fn fork_truncate_append_and_reset_preserve_every_retained_state() {
        for length in [1, 63, 64, 65, 127, 128, 129, 2048] {
            let mut original = FrameStates::default();
            for frame in 0..length { original.push(init_state(frame as f64, 0.0, 0.0, 0.0)); }
            for retained in [0, length / 2, length - 1, length] {
                let mut branch = original.clone();
                branch.truncate(retained);
                for frame in retained..retained + 100 {
                    branch.push(init_state(-(frame as f64), 0.0, 0.0, 0.0));
                }
                assert_eq!(original.len(), length);
                assert_eq!(branch.len(), retained + 100);
                for frame in 0..length { assert_eq!(original[frame].position[crate::PEG].x, frame as f64); }
                for frame in 0..branch.len() {
                    let expected = if frame < retained { frame as f64 } else { -(frame as f64) };
                    assert_eq!(branch[frame].position[crate::PEG].x, expected);
                }
                for chunk in 0..retained / CHUNK_FRAMES {
                    assert!(Rc::ptr_eq(&original.chunks[chunk], &branch.chunks[chunk]));
                }
                branch.clear();
                branch.push(init_state(5000.0, 0.0, 0.0, 0.0));
                assert_eq!(branch.len(), 1);
                assert_eq!(branch[0].position[crate::PEG].x, 5000.0);
                assert_eq!(original[0].position[crate::PEG].x, 0.0);
            }
        }
    }

    #[test]
    #[should_panic(expected = "frame outside the saved prefix")]
    fn truncated_tail_is_not_readable() {
        let mut states = FrameStates::new(init_state(0.0, 0.0, 0.0, 0.0));
        states.push(init_state(1.0, 0.0, 0.0, 0.0));
        let _other = states.clone();
        states.truncate(1);
        let _ = &states[1];
    }
}

//! Per-frame solver — bit-faithful port of lr-core's states/index.js (Point.step,
//! Binding) + constraints/index.js (Stick/RepelStick/BindStick/BindJoint) +
//! lines/SolidLine.collide, driven in LineEngine._getNextFrame order:
//!   step → 6×(resolve 22 iterating, collide 10) → resolve 3 non-iterating.
//!
//! The arithmetic here is REUSED VERBATIM from the proven kernel (bit-identical on
//! the committed tracks via verify:engine) — only the collision section is restructured
//! to use center-cell history and line lookup indexes equivalent to lr-core's
//! 3×3 neighborhood queries.

// Resolved positions belong to the collision that produced them, before later constraints.
pub(crate) type Collision = (u8, i32, i32, f64, f64);

use crate::history::CollisionHistory;
use crate::grid::{cell_cor_from_scaled, hash_int_pair, FlatIntMap, GRID_SIZE};
use crate::line::{Line, LineRef, MAX_FORCE_LENGTH};
use crate::{
    COLLIDING_POINTS, BASE, BUTT, GRAVITY_X, GRAVITY_Y, IS_POINT, ITER, ITERATE, JOINTS, LFOOT, LHAND, NENT,
    NOSE, PEG, RFOOT, RHAND, RIDER_MOUNTED, SHOULDER, STRING, TAIL,
};

#[derive(Clone, Copy)]
struct PointCell {
    key: i64,
    min_x: f64,
    max_x: f64,
    min_y: f64,
    max_y: f64,
    valid: bool,
    cell_x: i64,
    cell_y: i64,
    epoch: u32,
}

impl PointCell {
    const EMPTY: PointCell = PointCell {
        key: 0,
        min_x: 0.0,
        max_x: 0.0,
        min_y: 0.0,
        max_y: 0.0,
        valid: false,
        cell_x: 0,
        cell_y: 0,
        epoch: 0,
    };
}

const QUERY_SLOTS: usize = 64;

struct QueryCache {
    keys: [i64; QUERY_SLOTS],
    lines: [Vec<*const Line>; QUERY_SLOTS],
    epochs: [u32; QUERY_SLOTS],
    current_epoch: u32,
}

impl Default for QueryCache {
    fn default() -> Self {
        Self {
            keys: [0; QUERY_SLOTS],
            lines: std::array::from_fn(|_| Vec::new()),
            epochs: [0; QUERY_SLOTS],
            current_epoch: 1,
        }
    }
}

impl QueryCache {
    #[inline]
    fn invalidate(&mut self) {
        self.current_epoch = self.current_epoch.wrapping_add(1);
        if self.current_epoch == 0 {
            self.epochs.fill(0);
            self.current_epoch = 1;
        }
    }

    // Flatten only neighborhoods actually read. Buffers retain capacity across
    // eviction and invalidation; cell order and cross-cell duplicates are kept.
    #[inline]
    fn lookup(&mut self, grid: &FlatIntMap<Vec<LineRef>>, key: i64, cx: i64, cy: i64) -> &[*const Line] {
        let hash = (key as u64).wrapping_mul(0x9E3779B97F4A7C15);
        let slot = ((hash ^ (hash >> 32)) as usize) & (QUERY_SLOTS - 1);
        if self.epochs[slot] != self.current_epoch || self.keys[slot] != key {
            let lines = &mut self.lines[slot];
            lines.clear();
            for dx in -1..=1 {
                for dy in -1..=1 {
                    if let Some(bucket) = grid.get(&hash_int_pair(cx + dx, cy + dy)) {
                        lines.extend(bucket.iter().map(|entry| &**entry as *const Line));
                    }
                }
            }
            self.keys[slot] = key;
            self.epochs[slot] = self.current_epoch;
        }
        &self.lines[slot]
    }
}

pub(crate) struct LineCellCache {
    point_cells: [PointCell; NENT],
    point_lines: [Vec<*const Line>; NENT], // ordered lines passing this frame's direction predicate
    queries: QueryCache,
}

// Queries borrow immutable lines owned by the grid. Edits invalidate all lists;
// cache clones start empty and never copy borrowed pointers.
impl Clone for LineCellCache {
    fn clone(&self) -> Self {
        Self::default()
    }
}

impl Default for LineCellCache {
    fn default() -> Self {
        Self {
            point_cells: [PointCell::EMPTY; NENT],
            point_lines: std::array::from_fn(|_| Vec::new()),
            queries: QueryCache::default(),
        }
    }
}

impl LineCellCache {
    // Velocity is constant through all six sweeps, but changes at each step.
    // Refresh filtered point lists even when a replay reuses a frame index.
    // The shared neighborhood queries remain valid until a grid edit.
    #[inline]
    fn begin_frame(&mut self) {
        for point in &mut self.point_cells {
            point.epoch = 0;
        }
    }

    #[inline]
    pub(crate) fn invalidate(&mut self) {
        self.queries.invalidate();
        if self.queries.current_epoch == 1 {
            for point in &mut self.point_cells {
                point.epoch = 0;
            }
        }
    }

    #[inline]
    fn cache_point_lines(&mut self, grid: &FlatIntMap<Vec<LineRef>>, index: usize, vx: f64, vy: f64) {
        let point = &mut self.point_cells[index];
        if point.epoch == self.queries.current_epoch {
            return;
        }
        self.refresh_point_lines(grid, index, vx, vy);
    }

    // Keep the uncommon list rebuild out of each monomorphized point solver.
    #[inline(never)]
    fn refresh_point_lines(&mut self, grid: &FlatIntMap<Vec<LineRef>>, index: usize, vx: f64, vy: f64) {
        let point = &mut self.point_cells[index];
        let query = self.queries.lookup(grid, point.key, point.cell_x, point.cell_y);
        let lines = &mut self.point_lines[index];
        lines.clear();
        // Reserve once for the largest possible result before filtering. Growing
        // one pointer at a time fragments the WASM heap during long replays.
        lines.reserve(query.len());
        // Compact into the reserved buffer without Vec::push's capacity check
        // or a direction-dependent branch for each candidate. Rejected entries
        // overwrite the next unused slot; the accepted prefix stays ordered.
        let output = lines.as_mut_ptr();
        let mut count = 0;
        for &ptr in query {
            let line = unsafe { &*ptr };
            let passes = line.normx * vx + line.normy * vy > 0.0;
            // SAFETY: before input i, count <= i < query.len() <= capacity.
            // Pointers are Copy and have no destructor. The Vec stays length 0
            // until its fully initialized accepted prefix is published below.
            unsafe { output.add(count).write(ptr); }
            count += passes as usize;
        }
        // SAFETY: count <= query.len(), and every slot below count was written.
        unsafe { lines.set_len(count); }
        point.epoch = self.queries.current_epoch;
    }

    #[inline(always)]
    fn point_cell(&mut self, index: usize, px: f64, py: f64) -> i64 {
        Self::update_cell(&mut self.point_cells[index], px, py)
    }

    #[inline(always)]
    fn update_cell(cached: &mut PointCell, px: f64, py: f64) -> i64 {
        let scaled_x = px / GRID_SIZE;
        let scaled_y = py / GRID_SIZE;
        if cached.valid
            && scaled_x >= cached.min_x
            && scaled_x < cached.max_x
            && scaled_y >= cached.min_y
            && scaled_y < cached.max_y
        {
            return cached.key;
        }

        let cell_x = cell_cor_from_scaled(scaled_x);
        let cell_y = cell_cor_from_scaled(scaled_y);
        let min_x = cell_x as f64;
        let max_x = cell_x.checked_add(1).map_or(min_x, |value| value as f64);
        let min_y = cell_y as f64;
        let max_y = cell_y.checked_add(1).map_or(min_y, |value| value as f64);
        *cached = PointCell {
            key: hash_int_pair(cell_x, cell_y),
            min_x,
            max_x,
            min_y,
            max_y,
            valid: scaled_x.is_finite() && scaled_y.is_finite() && min_x < max_x && min_y < max_y,
            cell_x,
            cell_y,
            epoch: 0,
        };
        cached.key
    }
}

/// Coordinates that the solver reads and updates together stay adjacent.
#[derive(Clone, Copy, Default)]
#[repr(C)]
pub(crate) struct Vec2 {
    pub x: f64,
    pub y: f64,
}

impl Vec2 {
    #[inline(always)]
    fn add(self, other: Self) -> Self { Self { x: self.x + other.x, y: self.y + other.y } }
    #[inline(always)]
    fn sub(self, other: Self) -> Self { Self { x: self.x - other.x, y: self.y - other.y } }
    #[inline(always)]
    fn scaled(self, factor: f64) -> Self { Self { x: self.x * factor, y: self.y * factor } }
}

#[derive(Clone)]
pub(crate) struct State {
    pub position: [Vec2; NENT],
    pub previous: [Vec2; NENT],
    pub velocity: [Vec2; NENT],
    pub fsu: [i32; NENT],
}

#[inline]
fn dist(ax: f64, ay: f64, bx: f64, by: f64) -> f64 {
    let dx = bx - ax;
    let dy = by - ay;
    (dx * dx + dy * dy).sqrt()
}

pub(crate) fn init_state(sx: f64, sy: f64, svx: f64, svy: f64) -> State {
    let mut s = State {
        position: [Vec2::default(); NENT],
        previous: [Vec2::default(); NENT],
        velocity: [Vec2::default(); NENT],
        fsu: [-1; NENT],
    };
    for i in 0..NENT {
        if IS_POINT[i] {
            s.position[i].x = BASE[i].0 + sx;
            s.position[i].y = BASE[i].1 + sy;
            s.previous[i].x = s.position[i].x - svx;
            s.previous[i].y = s.position[i].y - svy;
            s.velocity[i].x = svx;
            s.velocity[i].y = svy;
        }
    }
    s
}

/// Rest lengths belong to the fixed rider topology, not to a frame cache.
/// Every solver call supplies a constant index, so release compilation folds
/// this expression while preserving its original rounded arithmetic.
#[inline(always)]
fn rest_length(k: usize) -> f64 {
    let (_, p1, p2, _, _, factor) = ITER[k];
    dist(BASE[p1].0, BASE[p1].1, BASE[p2].0, BASE[p2].1) * factor
}

#[inline(always)]
fn resolve_stick(s: &mut State, k: usize, p1: usize, p2: usize) {
    let a = s.position[p1];
    let b = s.position[p2];
    let length = dist(a.x, a.y, b.x, b.y);
    let gd = if length == 0.0 {
        0.0
    } else {
        (length - rest_length(k)) / length
    };
    let diff = gd * 0.5;
    let movement = a.sub(b).scaled(diff);
    s.position[p1] = a.sub(movement);
    s.position[p2] = b.add(movement);
}

#[inline(always)]
fn resolve_repel(s: &mut State, k: usize, p1: usize, p2: usize) {
    let a = s.position[p1];
    let b = s.position[p2];
    // Repels fire only when length < rest, which is rare (~2% — feet rarely closer
    // to the shoulder than rest). Gate the sqrt on len_sq < rest² so the common
    // inactive case skips the sqrt entirely. Inside the gate, `length` and the
    // applied math are byte-identical to the original (same len_sq, same sqrt, same
    // `length < rest` branch). The ONLY semantic difference is the gate vs the
    // original `length < rest` comparison, which can disagree in a ULP-wide band
    // where round(rest²) rounds below rest² — `verify`/`--diff` is the arbiter of
    // whether that band ever occurs for these inputs.
    let dx0 = b.x - a.x;
    let dy0 = b.y - a.y;
    let len_sq = dx0 * dx0 + dy0 * dy0;
    let r = rest_length(k);
    if len_sq < r * r {
        let length = len_sq.sqrt();
        if length < r {
            let gd = if length == 0.0 {
                0.0
            } else {
                (length - r) / length
            };
            let diff = gd * 0.5;
            let movement = a.sub(b).scaled(diff);
            s.position[p1] = a.sub(movement);
            s.position[p2] = b.add(movement);
        }
    }
}

#[inline(always)]
fn resolve_bind(
    s: &mut State,
    k: usize,
    p1: usize,
    p2: usize,
    bind: usize,
) {
    let a = s.position[p1];
    let b = s.position[p2];
    // `length` (a sqrt) is only used on the intact branch (fsu == -1, ~97% of the
    // time). Computing it lazily inside the branch skips the sqrt for the ~3%
    // broken-bind calls where it was discarded — strictly bit-identical (the value,
    // when used, is the same dist(); when unused it has no observable effect).
    if s.fsu[bind] == -1 {
        let length = dist(a.x, a.y, b.x, b.y);
        let gd = if length == 0.0 {
            0.0
        } else {
            (length - rest_length(k)) / length
        };
        let diff = gd * 0.5;
        if diff > ITER[k].4 * rest_length(k) * 0.5 {
            s.fsu[bind] = 0;
        } else {
            let movement = a.sub(b).scaled(diff);
            s.position[p1] = a.sub(movement);
            s.position[p2] = b.add(movement);
        }
    }
}

#[inline(always)]
fn resolve_iter_constraints(s: &mut State) {
    resolve_stick(s, 0, PEG, TAIL);
    resolve_stick(s, 1, TAIL, NOSE);
    resolve_stick(s, 2, NOSE, STRING);
    resolve_stick(s, 3, STRING, PEG);
    resolve_stick(s, 4, PEG, NOSE);
    resolve_stick(s, 5, STRING, TAIL);
    resolve_bind(s, 6, PEG, BUTT, RIDER_MOUNTED);
    resolve_bind(s, 7, TAIL, BUTT, RIDER_MOUNTED);
    resolve_bind(s, 8, NOSE, BUTT, RIDER_MOUNTED);
    resolve_stick(s, 9, SHOULDER, BUTT);
    resolve_stick(s, 10, SHOULDER, LHAND);
    resolve_stick(s, 11, SHOULDER, RHAND);
    resolve_stick(s, 12, BUTT, LFOOT);
    resolve_stick(s, 13, BUTT, RFOOT);
    resolve_stick(s, 14, SHOULDER, RHAND);
    resolve_bind(s, 15, SHOULDER, PEG, RIDER_MOUNTED);
    resolve_bind(s, 16, STRING, LHAND, RIDER_MOUNTED);
    resolve_bind(s, 17, STRING, RHAND, RIDER_MOUNTED);
    resolve_bind(s, 18, LFOOT, NOSE, RIDER_MOUNTED);
    resolve_bind(s, 19, RFOOT, NOSE, RIDER_MOUNTED);
    resolve_repel(s, 20, SHOULDER, LFOOT);
    resolve_repel(s, 21, SHOULDER, RFOOT);
}

#[inline(always)]
#[allow(clippy::too_many_arguments)]
unsafe fn collide_point<const TRACK: bool>(
    s: &mut State,
    grid: &FlatIntMap<Vec<LineRef>>,
    events: &mut Vec<Collision>,
    frame_index: i32,
    history: &mut CollisionHistory,
    line_cache: &mut LineCellCache,
    it: u8,
    index: usize,
    fric: f64,
) {
    let (mut pxi, mut pyi, vxi, vyi) = (
        s.position.get_unchecked(index).x,
        s.position.get_unchecked(index).y,
        s.velocity.get_unchecked(index).x,
        s.velocity.get_unchecked(index).y,
    );
    let center_cell = line_cache.point_cell(index, pxi, pyi);
    // addToGrid (A): pre-collision snapshot.
    if TRACK {
        history.record_point(
            center_cell,
            frame_index,
            pxi,
            pyi,
            vxi,
            vyi,
        );
    }
    line_cache.cache_point_lines(grid, index, vxi, vyi);
    let lns = &line_cache.point_lines[index];
    if !lns.is_empty() {
        let (mut prevxi, mut prevyi) = (s.previous.get_unchecked(index).x, s.previous.get_unchecked(index).y);
        for &line in lns {
            // Entries point into immutable batch geometry owned by the grid.
            // Only point_cells is updated below; this query stays fixed during
            // the sweep even when a collision moves the entity to another cell.
            let l = &*line;
            let ox = pxi - l.p1x;
            let oy = pyi - l.p1y;
            let perp_comp = l.normx * ox + l.normy * oy;
            let line_pos = (l.vecx * ox + l.vecy * oy) * l.inv_len_sq;
            if perp_comp > 0.0
                && perp_comp < MAX_FORCE_LENGTH
                && line_pos >= l.left_bound
                && line_pos <= l.right_bound
            {
                let tx = l.normx * perp_comp - pxi;
                let ty = l.normy * perp_comp - pyi;
                let posx = tx * -1.0;
                let posy = ty * -1.0;
                let (mut fvx, mut fvy) = if fric == 0.0 {
                    (prevxi, prevyi)
                } else {
                    let mut fvx = (l.normy * fric) * perp_comp;
                    let mut fvy = ((-l.normx) * fric) * perp_comp;
                    if prevxi >= posx {
                        fvx = fvx * -1.0;
                    }
                    if prevyi < posy {
                        fvy = fvy * -1.0;
                    }
                    (fvx + prevxi, fvy + prevyi)
                };
                if l.is_acc {
                    fvx = fvx + l.accx;
                    fvy = fvy + l.accy;
                }
                s.position.get_unchecked_mut(index).x = posx;
                s.position.get_unchecked_mut(index).y = posy;
                s.previous.get_unchecked_mut(index).x = fvx;
                s.previous.get_unchecked_mut(index).y = fvy;
                pxi = posx;
                pyi = posy;
                prevxi = fvx;
                prevyi = fvy;
                events.push((it, l.id, index as i32, posx, posy));
                // addToGrid (B) + addToCollisions: post-collision, centered on the MOVED entity.
                if TRACK {
                    let pcell = LineCellCache::update_cell(&mut line_cache.point_cells[index], pxi, pyi);
                    history.record_point(
                        pcell,
                        frame_index,
                        pxi,
                        pyi,
                        vxi,
                        vyi,
                    );
                    history.record_collision(l.id, frame_index);
                }
            }
        }
    }
}

/// One frame: step → 6×(constraints, collision) → BindJoints. `events` collects
/// (iteration, line_id, point_idx) per collision (for getUpdatesAtFrame). When
/// `track`, point snapshots and line collisions are recorded in `history` at
/// `frame_index`; recording is purely additive — it does not affect the physics.
#[allow(clippy::too_many_arguments)]
// Keep the large solver out of the frequently called cached-read path.
#[inline(never)]
// The WASM module requires SIMD128. Only this solver enables vectorization;
// all equations remain ordinary scalar Rust with their original order.
#[cfg_attr(target_arch = "wasm32", target_feature(enable = "simd128"))]
pub(crate) unsafe fn step_state<const TRACK: bool>(
    s: &mut State,
    grid: &FlatIntMap<Vec<LineRef>>,
    events: &mut Vec<Collision>,
    frame_index: i32,
    history: &mut CollisionHistory,
    line_cache: &mut LineCellCache,
    mut trace: Option<&mut CollisionTrace>,
) {
    if TRACK { history.begin_frame(); }
    line_cache.begin_frame();
    // step
    for i in 0..NENT {
        if IS_POINT[i] {
            let nvx = (s.position[i].x - s.previous[i].x) * (1.0 - 0.0) + GRAVITY_X;
            let nvy = (s.position[i].y - s.previous[i].y) * (1.0 - 0.0) + GRAVITY_Y;
            let nx = s.position[i].x + nvx;
            let ny = s.position[i].y + nvy;
            s.previous[i].x = s.position[i].x;
            s.previous[i].y = s.position[i].y;
            s.position[i].x = nx;
            s.position[i].y = ny;
            s.velocity[i].x = nvx;
            s.velocity[i].y = nvy;
        } else if s.fsu[i] != -1 {
            s.fsu[i] += 1;
        }
    }

    for it in 0..ITERATE {
        unsafe {
            resolve_iter_constraints(s);
            if let Some(trace) = trace.as_deref_mut() { trace.record(s, it); }
            let it = it as u8;
            for &(index, friction) in &COLLIDING_POINTS {
                collide_point::<TRACK>(s, grid, events, frame_index, history, line_cache, it, index, friction);
            }
        }
    }

    for &(p1, p2, q1, q2, bind) in JOINTS.iter() {
        let ax = s.position[p2].x - s.position[p1].x;
        let ay = s.position[p2].y - s.position[p1].y;
        let bx = s.position[q2].x - s.position[q1].x;
        let by = s.position[q2].y - s.position[q1].y;
        let cross = ax * by - ay * bx;
        if cross >= 0.0 {
            // allow
        } else if s.fsu[bind] == -1 {
            s.fsu[bind] = 0;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn ids(cache: &mut LineCellCache, grid: &FlatIntMap<Vec<LineRef>>, x: f64, y: f64) -> Vec<i32> {
        cache.point_cell(PEG,x, y);
        cache.cache_point_lines(grid, PEG, 0.0, 1.0);
        cache.point_lines[PEG].iter().map(|&line| unsafe { (*line).id }).collect()
    }

    #[test]
    fn query_cache_invalidates_hits_misses_clones_and_epoch_wrap() {
        use crate::line::{build_line, push_line, remove_line};
        let mut grid = FlatIntMap::default();
        let mut cache = LineCellCache::default();
        assert!(ids(&mut cache, &grid, 1.0, 1.0).is_empty());
        let line = build_line(1, 0.0, 5.0, 10.0, 5.0, 0, 0);
        let cells = line.cells();
        cache.invalidate();
        push_line(&mut grid, &line, cells);
        assert_eq!(ids(&mut cache, &grid, 1.0, 1.0), vec![1]);
        let mut cloned = cache.clone();
        let mut other = grid.clone();
        remove_line(&mut other, 1, &cells);
        assert!(ids(&mut cloned, &other, 1.0, 1.0).is_empty());
        cache.invalidate();
        remove_line(&mut grid, 1, &cells);
        for key in 100..1000 { grid.get_or_insert_default(key); }
        assert!(ids(&mut cache, &grid, 1.0, 1.0).is_empty());
        assert!(ids(&mut cache, &grid, 1400.0, -1400.0).is_empty());
        cache.queries.current_epoch = u32::MAX;
        cache.invalidate();
        assert_eq!(cache.queries.current_epoch, 1);
        assert!(cache.queries.epochs.iter().all(|&e| e == 0));
        assert!(cache.point_cells.iter().all(|p| p.epoch == 0));
        assert!(ids(&mut cache, &grid, 1400.0, -1400.0).is_empty());
    }

    #[test]
    fn flat_query_preserves_duplicates_and_survives_point_movement_during_sweep() {
        use crate::line::{build_line, push_line, remove_line};
        let mut grid = FlatIntMap::default();
        let mut cache = LineCellCache::default();
        for (id, cells) in [(1, vec![(-1, -1)]), (2, vec![(-1, 0)]), (3, vec![(-1, -1), (-1, 0)])] {
            push_line(&mut grid, &build_line(id, 0.0, 5.0, 10.0, 5.0, 0, 0), &cells);
        }
        assert_eq!(ids(&mut cache, &grid, 1.0, 1.0), vec![3, 1, 3, 2]);
        let query = &cache.point_lines[PEG];
        LineCellCache::update_cell(&mut cache.point_cells[PEG], 14.0, 1.0);
        assert_eq!(query.iter().map(|&l| unsafe { (*l).id }).collect::<Vec<_>>(), vec![3, 1, 3, 2]);
        assert!(ids(&mut cache, &grid, 14.0, 1.0).is_empty());
        cache.invalidate();
        push_line(&mut grid, &build_line(4, 0.0, 5.0, 10.0, 5.0, 0, 0), &[(2, 0)]);
        assert_eq!(ids(&mut cache, &grid, 14.0, 1.0), vec![4]);
        cache.invalidate();
        remove_line(&mut grid, 4, &[(2, 0)]);
        assert!(ids(&mut cache, &grid, 14.0, 1.0).is_empty());
    }

    #[test]
    fn shared_query_eviction_does_not_replace_a_points_cached_lines() {
        use crate::line::{build_line, push_line};
        let mut grid = FlatIntMap::default();
        push_line(&mut grid, &build_line(1, 0.0, 5.0, 10.0, 5.0, 0, 0), &[(0, 0)]);
        let mut cache = LineCellCache::default();
        assert_eq!(ids(&mut cache, &grid, 1.0, 1.0), vec![1]);
        for cx in 1..1024 {
